def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    """
    Optimize the placement of aisles in a classroom to minimize the amount of chatting between students.

    Args:
        M (int): The number of rows in the classroom.
        N (int): The number of columns in the classroom.
        K (int): The number of horizontal aisles to add.
        L (int): The number of vertical aisles to add.
        D (int): The number of chatting pairs in the classroom.
        chatting_pairs (list of tuples): A list of tuples, each containing the positions (Xi, Yi) and (Pi, Qi) of a chatting pair.

    Returns:
        (str, str): Two space-separated strings representing the optimal row and column indices for the aisles.
    """
    # Basic validation
    if not (isinstance(M, int) and isinstance(N, int) and isinstance(K, int) and isinstance(L, int) and isinstance(D, int)):
        raise TypeError("All parameters must be integers.")
    if M <= 0 or N <= 0 or K < 0 or L < 0 or D < 0:
        raise ValueError("Dimensions and counts must be non-negative, with M and N positive.")
    if K > M - 1 or L > N - 1:
        raise ValueError("Number of aisles cannot exceed available positions.")
    if len(chatting_pairs) != D:
        raise ValueError("Length of chatting_pairs does not match D.")
    for pair in chatting_pairs:
        if len(pair) != 4:
            raise ValueError("Each chatting pair must contain four integers.")
        x1, y1, x2, y2 = pair
        if not (1 <= x1 <= M and 1 <= y1 <= N and 1 <= x2 <= M and 1 <= y2 <= N):
            raise ValueError("Student positions must be within classroom bounds.")

    # Precompute which pairs are separated by each possible aisle
    row_separators = {r: set() for r in range(1, M)}   # aisle between r and r+1
    col_separators = {c: set() for c in range(1, N)}   # aisle between c and c+1

    for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
        # Horizontal aisle
        if x1 != x2:
            r_min, r_max = sorted((x1, x2))
            for r in range(r_min, r_max):
                row_separators[r].add(idx)
        # Vertical aisle
        if y1 != y2:
            c_min, c_max = sorted((y1, y2))
            for c in range(c_min, c_max):
                col_separators[c].add(idx)

    # Helper to compute union size for given sets
    def union_size(row_set, col_set):
        total = set()
        for r in row_set:
            total.update(row_separators[r])
        for c in col_set:
            total.update(col_separators[c])
        return len(total)

    # Decide whether to brute force or use greedy
    from math import comb
    max_combinations = 10**6
    try:
        row_combos = comb(M - 1, K) if K <= M - 1 else 0
        col_combos = comb(N - 1, L) if L <= N - 1 else 0
    except ValueError:
        row_combos = col_combos = 0
    total_combos = row_combos * col_combos

    best_rows = []
    best_cols = []
    best_count = -1

    if total_combos <= max_combinations:
        import itertools
        row_candidates = list(range(1, M))
        col_candidates = list(range(1, N))
        for r_combo in itertools.combinations(row_candidates, K):
            for c_combo in itertools.combinations(col_candidates, L):
                cnt = union_size(r_combo, c_combo)
                if cnt > best_count:
                    best_count = cnt
                    best_rows = list(r_combo)
                    best_cols = list(c_combo)
    else:
        # Greedy selection
        chosen_rows = []
        chosen_cols = []
        covered = set()

        # Select horizontal aisles
        for _ in range(K):
            best_r = None
            best_new = -1
            for r in range(1, M):
                if r in chosen_rows:
                    continue
                new = len(row_separators[r] - covered)
                if new > best_new:
                    best_new = new
                    best_r = r
            if best_r is None:
                break
            chosen_rows.append(best_r)
            covered.update(row_separators[best_r])

        # Select vertical aisles
        for _ in range(L):
            best_c = None
            best_new = -1
            for c in range(1, N):
                if c in chosen_cols:
                    continue
                new = len(col_separators[c] - covered)
                if new > best_new:
                    best_new = new
                    best_c = c
            if best_c is None:
                break
            chosen_cols.append(best_c)
            covered.update(col_separators[best_c])

        best_rows = sorted(chosen_rows)
        best_cols = sorted(chosen_cols)

    # Format output strings
    row_str = " ".join(str(r) for r in sorted(best_rows))
    col_str = " ".join(str(c) for c in sorted(best_cols))
    return (row_str, col_str)

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If inputs are logically inconsistent (e.g., wrong length of coeffs).
    """
    # Validate inputs
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    if not isinstance(coeffs, list):
        raise TypeError("coeffs must be a list")
    if len(coeffs) != n + 1:
        raise ValueError(f"coeffs length must be {n + 1} for degree {n}")
    for c in coeffs:
        if not isinstance(c, int):
            raise TypeError("All coefficients must be integers")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # Basic validation: encoded and original must be same length
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e_char, o_char in zip(encoded, original):
        # Ensure characters are uppercase letters
        if not (e_char.isalpha() and o_char.isalpha()):
            return "Failed"
        e_char = e_char.upper()
        o_char = o_char.upper()

        # Check forward mapping consistency
        if e_char in mapping:
            if mapping[e_char] != o_char:
                return "Failed"
        else:
            mapping[e_char] = o_char

        # Check reverse mapping consistency (bijection)
        if o_char in reverse_mapping:
            if reverse_mapping[o_char] != e_char:
                return "Failed"
        else:
            reverse_mapping[o_char] = e_char

    # All 26 letters must be represented in the mapping
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    try:
        decoded_chars = [mapping[ch.upper()] for ch in message]
    except KeyError:
        return "Failed"

    return ''.join(decoded_chars)

def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of pairs of positive integers (P, Q) such that P and Q have x0 as their greatest
    common divisor (GCD) and y0 as their least common multiple (LCM).

    Args:
        x0 (int): The GCD that each pair (P, Q) must have.
        y0 (int): The LCM that each pair (P, Q) must have.

    Returns:
        int: The count of all possible pairs (P, Q) that meet the specified criteria.
    """
    # Validate inputs
    if x0 <= 0 or y0 <= 0:
        return 0
    if y0 % x0 != 0:
        return 0

    n = y0 // x0

    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    count = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            a = i
            b = n // i
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
        i += 1
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    from collections import deque
    from typing import Union

    # Basic validation
    if not isinstance(A, str) or not isinstance(B, str) or not isinstance(rules, list):
        raise TypeError("A and B must be strings, rules must be a list of tuples.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2 and isinstance(rule[0], str) and isinstance(rule[1], str)):
            raise ValueError("Each rule must be a tuple of two strings (source, target).")

    # If already equal
    if A == B:
        return 0

    max_depth = 10
    visited = {A}
    queue = deque([(A, 0)])

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue
        next_depth = depth + 1
        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return next_depth
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, next_depth))
                start = idx + 1  # allow overlapping matches
    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Normalize scenario to upper case for comparison
    scenario = scenario.upper()

    # Helper to parse a single statement
    def parse_statement(statement: str, speaker: str):
        # Ignore statements about days of the week
        stmt_lower = statement.lower()
        for day in days_of_week:
            if day.lower() in stmt_lower:
                return None  # skip this statement

        # Strip trailing punctuation and split
        s = statement.strip().rstrip('.')
        words = s.split()
        if len(words) < 3:
            return None

        # Determine subject and guilt status
        if words[0].lower() == 'i':
            subject = speaker.upper()
            if words[1].lower() != 'am':
                return None
            if words[2].lower() == 'guilty':
                guilty = True
            elif words[2].lower() == 'not' and len(words) >= 4 and words[3].lower() == 'guilty':
                guilty = False
            else:
                return None
        else:
            subject = words[0].upper()
            if words[1].lower() != 'is':
                return None
            if words[2].lower() == 'guilty':
                guilty = True
            elif words[2].lower() == 'not' and len(words) >= 4 and words[3].lower() == 'guilty':
                guilty = False
            else:
                return None

        return subject, guilty

    # Evaluate each statement
    for speaker, stmts in statements.items():
        speaker_upper = speaker.upper()
        for stmt in stmts:
            parsed = parse_statement(stmt, speaker_upper)
            if parsed is None:
                continue  # skip unparsable or day-related statements
            subject, guilty = parsed
            # Determine truth value of the statement
            truth = (subject == scenario) if guilty else (subject != scenario)
            # Check consistency with liar status
            if speaker_upper in liar_count:
                if truth:
                    return False  # liar made a true statement
            else:
                if not truth:
                    return False  # truth-teller made a false statement
    return True

def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    # Basic validation
    if not isinstance(T, int) or not isinstance(M, int):
        raise TypeError("T and M must be integers")
    if T < 0:
        raise ValueError("T must be non-negative")
    if M < 0:
        raise ValueError("M must be non-negative")
    if not isinstance(herbs, list):
        raise TypeError("herbs must be a list of tuples")
    if len(herbs) != M:
        # If mismatch, adjust M to actual length
        M = len(herbs)

    # If no time or no herbs, result is 0
    if T == 0 or M == 0:
        return 0

    # Initialize DP array
    dp = [0] * (T + 1)

    for idx, (time_cost, value) in enumerate(herbs):
        # Validate each herb entry
        if not isinstance(time_cost, int) or not isinstance(value, int):
            raise TypeError(f"Herb at index {idx} must contain integers")
        if time_cost < 0 or value < 0:
            raise ValueError(f"Herb at index {idx} has negative time or value")

        # Skip herbs that cannot be taken due to time cost
        if time_cost > T:
            continue

        # 0/1 knapsack: iterate backwards
        for t in range(T, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp)

